(()=>{function add(){const menu=document.querySelector('.admin-menu');if(!menu||menu.querySelector('[data-kitchen-stock-link]'))return;const a=document.createElement('a');a.className='menu-card';a.href='kitchen-stock/';a.dataset.kitchenStockLink='1';a.innerHTML='<span class="menu-icon">▤</span><div><b>Остатки кухонь</b><small>Бухара и Правда: начало, приготовлено, перемещено, конец дня</small></div><span class="menu-arrow">›</span>';const journal=[...menu.querySelectorAll('.menu-card')].find(x=>/Журнал документов/.test(x.textContent));journal?menu.insertBefore(a,journal):menu.appendChild(a)}new MutationObserver(add).observe(document.getElementById('admin-app'),{childList:true,subtree:true});add()})();